#include <circuit_generator.h>
#include <decoder/pymatching.h>
#include <decoder/concat_mwpm.h>
#include <decoder/blossom5.h>
#include <decoder/libra.h>
#include <decoder/harmony.h>
#include <decoder/seeded.h>
#include <decoder/uf.h>
// Generated by OpenAI GPT-6-Luna to include the decoder's dedicated Tesseract wrapper header.
#include <decoder/tesseract.h>
#include <sampler.h>
#include "code_catalog.h"
#include "tesseract_options.h"

#include <stim/util_top/circuit_to_dem.h>

#include <argparse/argparse.h>

#include <iostream>
#include <algorithm>
#include <cmath>
#include <limits>
#include <stdexcept>
#include <exception>
#include <filesystem>

#if defined(ENABLE_MPI)
#include <mpi.h>
#endif

////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////

static int
run_cli(int argc, char* argv[], int world_rank)
{
    /*
     * Simulation configuration:
     * */
    std::string decoder_name;
    std::string code_name;
    int64_t d,
            r;
    double p;
    ExperimentConfig conf;
    ComponentErrorDistribution noise_distribution;
    int64_t noise_seed = 0;
    // Contributor: OpenAI Codex. Ideal data/readout noise selectors.
    bool code_capacity{false}, phenomenological{false};
    double measurement_error_rate{-1};
    TesseractOptions tesseract_options; // Author: OpenAI Codex.

    /*
     * PyMatching parameters:
     * */
    bool enable_gap{false};
    bool enable_cluster_gap{false};
    bool print_cluster_gap_histogram{false};
    bool correlated_pymatching{false};
    bool concat_boundary_gap{false}; // Author: OpenAI Codex. First-stage boundary parity sectors.
    bool concat_bp{false}; // Author: OpenAI Codex. Flag BP updates both matching stages.
    bool concat_flag_renormalization{false}; // Author: OpenAI Codex, paper Sec. III D.
    bool decoder_debug{false};
    // Contributor: OpenAI Codex. Optional fixed first-stage probability ensemble.
    int64_t concat_ensemble_size{1};
    int64_t concat_ensemble_seed{20261024};
    // OpenAI GPT-6-Sol: Let CLI experiments opt into interior opposite-basis checks.
    bool include_opposite_basis_detectors{false};
    dec::Libra::Config libra_config;
    dec::SeededMatchingConfig seeded_config;
    std::string seed_decoder = "pymatching";
    std::string second_decoder = "correlated_pymatching";
    std::string seed_gap = "cluster";
    int64_t libra_ensemble_size = 60;
    int64_t libra_seed = static_cast<int64_t>(libra_config.seed);
    int64_t uf_weight_scale = 1024;
    dec::Harmony::Config harmony_config;
    int64_t harmony_ensemble_size = 100;
    int64_t harmony_sentinel_size = 0;
    int64_t harmony_seed = static_cast<int64_t>(harmony_config.seed);
    bool harmony_full_ensemble = false;
    std::string harmony_pooling = "sum_likelihood";

    ARGPARSE parser;
    parser.required("decoder-name", "Decoder: pymatching, blossom5, tesseract, libra, seeded, uf, harmony, concat_mwpm", decoder_name);
    parser.optional("-d", "--distance", "Planar code distance (ignored for named hyperbolic codes)", d, 5)
        .optional("-c", "--code", "Code: sc, cc666, cc488, or a hycc_* catalog name", code_name, "")
        .optional("-p", "--physical-error-rate", "Physical error rate", p, 1e-3)
        .optional("-r", "--rounds", "Number of rounds (-1 = distance; code capacity uses one)", r, -1)
        .optional("-cap", "--code-capacity", "Use one-round code-capacity noise", code_capacity, false)
        .optional("-pheno", "--phenomenological", "Use data and check-readout noise", phenomenological, false)
        .optional("", "--measurement-error-rate", "Phenomenological check-result flip probability (-1 = physical p)", measurement_error_rate, -1.0)
        .optional("-v", "--verbose", "Verbosity level", conf.verbosity, 0)
        .optional("", "--seed", "Sampling seed (MPI ranks use distinct streams)", conf.seed, 0)
        .optional("", "--noise-log-stddev", "Component error-rate spread: standard deviation in log space (0 = uniform)", noise_distribution.log_stddev, 0.0)
        .optional("", "--noise-seed", "Fixed hardware error-model seed (shared across MPI ranks)", noise_seed, 0)
        .optional("-m", "--method", "Sampler method: monte_carlo or rare_event", conf.method, "monte_carlo")
        .optional("-pp", "--print-progress", "Print simulation progress", conf.print_progress, false)
        .optional("-g", "--gap", "Enable complementary gap estimation (pymatching only)", enable_gap, false)
        .optional("", "--cluster-gap", "Full cluster soft output in dB (uncorrelated pymatching or uf)", enable_cluster_gap, false)
        .optional("", "--cluster-gap-histogram", "Print cluster-gap bins (requires --cluster-gap)", print_cluster_gap_histogram, false)
        .optional("", "--correlated", "PyMatching: use two-pass correlated MWPM", correlated_pymatching, false)
        .optional("", "--include-opposite-basis-detectors", "Include interior opposite-basis check detectors", include_opposite_basis_detectors, false)
        .optional("", "--debug", "Color-code decoders: populate and print decoder-specific debug information", decoder_debug, false)
        .optional("", "--concat-boundary-gap", "ConcatMWPM: test all four spatial-boundary parity sectors per color", concat_boundary_gap, false)
        .optional("", "--concat-bp", "ConcatMWPM: condition hyperedges on flags and available opposite-basis checks using BP", concat_bp, false)
        .optional("", "--concat-flag-renormalization", "ConcatMWPM: use raw flag-fault probabilities and p^m ordinary-edge suppression", concat_flag_renormalization, false)
        .optional("", "--concat-ensemble", "ConcatMWPM: number of first-stage graphs per color (1 = unperturbed)", concat_ensemble_size, 1)
        .optional("", "--concat-seed", "ConcatMWPM: fixed first-stage ensemble seed", concat_ensemble_seed, concat_ensemble_seed)
        .optional("", "--uf-weight-scale", "Union-find: quantization units per natural-log weight", uf_weight_scale, 1024)

        .optional("", "--seed-decoder", "SeededMatching first decoder: pymatching or uf", seed_decoder, "pymatching")
        .optional("", "--second-decoder", "SeededMatching second decoder: correlated_pymatching or libra", second_decoder, "correlated_pymatching")
        .optional("", "--seed-postprocess", "Retain unaffected, locally preferred seed pairs", seeded_config.postprocess, false)
        .optional("", "--seed-gap", "Libra gate: cluster or complementary", seed_gap, "cluster")
        .optional("", "--seed-gap-threshold-db", "Seed gap threshold for Libra ensembling", seeded_config.libra_gap_threshold_db, 40.0)

        .optional("", "--libra-ensemble-size", "Libra: number of perturbed matchers", libra_ensemble_size, 60)
        .optional("", "--libra-gap-threshold-db", "Libra: ensemble trigger gap in dB", libra_config.gap_threshold_db, 20.0)
        .optional("", "--libra-seed", "Libra: shared ensemble-prior seed", libra_seed, libra_seed)
        .optional("", "--libra-profile", "Libra: collect decoding phase times", libra_config.profile, false)
        .optional("", "--libra-validate", "Libra: verify returned error configurations", libra_config.validate, false)

        .optional("", "--harmony-ensemble-size", "Harmony: total number of ensemble members", harmony_ensemble_size, 100)
        .optional("", "--harmony-sentinel-size", "Harmony: initial members (0 = min(4, ensemble size))", harmony_sentinel_size, 0)
        .optional("", "--harmony-full-ensemble", "Harmony: run every member on every shot", harmony_full_ensemble, false)
        .optional("", "--harmony-seed", "Harmony: shared ensemble-prior seed", harmony_seed, harmony_seed)
        .optional("", "--harmony-pooling", "Harmony: sum_likelihood or vote", harmony_pooling, "sum_likelihood")

        .optional("", "--mc-max-samples", "Monte-carlo: max shots to sample", conf.monte_carlo.max_samples, 1000000)
        .optional("", "--mc-stop-at-errors", "Monte-carlo: stop after this many logical errors", conf.monte_carlo.stop_at_error_count, 25)

        .optional("", "--rare-samples-per-level", "Rare-event: samples per error level", conf.rare_event.samples_per_level, 10000)
        .optional("", "--rare-max-errors-per-level", "Rare-event: max errors per error level", conf.rare_event.max_errors_per_level, 25)
        .optional("", "--rare-max-level", "Rare-event: exclusive active-error count limit", conf.rare_event.max_level, 128)
        .optional("", "--rare-relative-tail-tolerance", "Rare-event: stop when remaining bound < fraction of accumulated LER (0 disables)", conf.rare_event.relative_tail_tolerance, 0.1)
        .optional("", "--rare-tail-tolerance", "Rare-event: maximum omitted-count contribution bound", conf.rare_event.tail_tolerance, 1e-12);
    tesseract_options.add_arguments(parser);
    parser.parse(argc, argv);
    tesseract_options.validate(decoder_name,argc,argv);
    const bool color_decoder = decoder_name == "concat_mwpm";
    if (code_name.empty()) code_name = color_decoder ? "cc666" : "sc";
    const CatalogCode* external_code = find_external_code(code_name);
    if (external_code) d = external_code->default_rounds;
    if (d < 3 || d > std::numeric_limits<uint32_t>::max())
        throw std::invalid_argument("Distance must be at least 3 and fit uint32_t");
    if (r < -1) throw std::invalid_argument("--rounds must be -1 or positive");
    if (code_capacity && phenomenological)
        throw std::invalid_argument("--code-capacity and --phenomenological are mutually exclusive");
    if (code_capacity && r >= 0 && r != 1)
        throw std::invalid_argument("Code capacity requires exactly one round");
    if (r < 0) r = code_capacity ? 1 : d;
    if (r < 1) throw std::invalid_argument("Number of rounds must be positive");
    if (measurement_error_rate != -1 && !phenomenological)
        throw std::invalid_argument("--measurement-error-rate requires --phenomenological");
    if (!std::isfinite(measurement_error_rate) || measurement_error_rate < -1 ||
        (measurement_error_rate < 0 && measurement_error_rate != -1))
        throw std::invalid_argument("Invalid measurement error probability");
    if (measurement_error_rate == -1) measurement_error_rate = p;
    const std::string noise_model = code_capacity ? "code_capacity" : phenomenological ? "phenomenological" : "SI1000";
    if (noise_seed < 0)
        throw std::invalid_argument("--noise-seed must be nonnegative");
    noise_distribution.seed = static_cast<uint64_t>(noise_seed);
    noise_distribution.validate();

    if (decoder_name != "pymatching" && decoder_name != "blossom5" &&
        decoder_name != "tesseract" && decoder_name != "libra" && decoder_name != "seeded" &&
        decoder_name != "uf" && decoder_name != "harmony" && decoder_name != "concat_mwpm")
    {
        throw std::invalid_argument("Unknown decoder name: " + decoder_name);
    }
    if (decoder_debug && !color_decoder)
        throw std::invalid_argument("--debug supports concat_mwpm");
    if (code_name != "sc" && code_name != "cc666" && code_name != "cc488" && !external_code)
        throw std::invalid_argument("Unknown code: " + code_name);
    if (color_decoder && (code_name != "cc666" && code_name != "cc488" && !external_code))
        throw std::invalid_argument(decoder_name+" requires a color code");
    if (color_decoder && enable_gap)
        throw std::invalid_argument("--gap is not available for "+decoder_name);

    if (conf.method != "monte_carlo" && conf.method != "rare_event")
        throw std::invalid_argument("Unknown sampler method: " + conf.method);
    if (concat_ensemble_size < 1)
        throw std::invalid_argument("--concat-ensemble must be positive");
    if (concat_ensemble_seed < 0)
        throw std::invalid_argument("--concat-seed must be nonnegative");
    if ((concat_ensemble_size != 1 || concat_ensemble_seed != 20261024) && decoder_name != "concat_mwpm")
        throw std::invalid_argument("--concat-ensemble and --concat-seed require concat_mwpm");
    if (concat_boundary_gap && decoder_name != "concat_mwpm")
        throw std::invalid_argument("--concat-boundary-gap requires concat_mwpm");
    if (concat_bp && decoder_name != "concat_mwpm")
        throw std::invalid_argument("--concat-bp requires concat_mwpm");
    if (concat_bp && concat_flag_renormalization)
        throw std::invalid_argument("--concat-bp replaces --concat-flag-renormalization; choose one");
    if (concat_flag_renormalization && decoder_name != "concat_mwpm")
        throw std::invalid_argument("--concat-flag-renormalization requires concat_mwpm");
    if (correlated_pymatching && decoder_name != "pymatching")
        throw std::invalid_argument("--correlated is only available for pymatching");
    if (enable_cluster_gap && (decoder_name != "pymatching" && decoder_name != "uf"))
        throw std::invalid_argument("--cluster-gap supports only pymatching and uf");
    if (enable_cluster_gap && (enable_gap || correlated_pymatching))
        throw std::invalid_argument("--cluster-gap cannot be combined with --gap or --correlated");
    if (print_cluster_gap_histogram && !enable_cluster_gap)
        throw std::invalid_argument("--cluster-gap-histogram requires --cluster-gap");
    if (correlated_pymatching && enable_gap)
        throw std::invalid_argument("--correlated cannot currently be combined with --gap");
    if (decoder_name == "seeded")
    {
        if (seed_decoder != "pymatching" && seed_decoder != "uf")
            throw std::invalid_argument("Seed decoder must be pymatching or uf");
        if (second_decoder != "correlated_pymatching" && second_decoder != "libra")
            throw std::invalid_argument("Second decoder must be correlated_pymatching or libra");
        if (seed_gap != "cluster" && seed_gap != "complementary")
            throw std::invalid_argument("Seed gap must be cluster or complementary");
        if (second_decoder == "libra" && seed_decoder == "uf" && seed_gap == "complementary")
            throw std::invalid_argument("Complementary gap requires a PyMatching seed");
        seeded_config.libra_gap_mode = seed_gap == "cluster"
            ? dec::SeedGapMode::Cluster : dec::SeedGapMode::Complementary;
        if (uf_weight_scale <= 0)
            throw std::invalid_argument("UnionFind weight scale must be positive");
    }

    conf.rare_event.start_level = 0;
    libra_config.ensemble_size = static_cast<size_t>(libra_ensemble_size);
    libra_config.seed = static_cast<uint64_t>(libra_seed);
    if (decoder_name == "harmony") {
        if (harmony_ensemble_size <= 0 || harmony_sentinel_size < 0 ||
            harmony_sentinel_size > harmony_ensemble_size)
            throw std::invalid_argument("Harmony requires positive ensemble size and sentinel size in [0, ensemble size]");
        harmony_config.ensemble_size = static_cast<size_t>(harmony_ensemble_size);
        harmony_config.sentinel_size = static_cast<size_t>(harmony_sentinel_size
            ? harmony_sentinel_size : std::min<int64_t>(4, harmony_ensemble_size));
        harmony_config.layered = !harmony_full_ensemble;
        harmony_config.seed = static_cast<uint64_t>(harmony_seed);
        if (harmony_pooling == "sum_likelihood")
            harmony_config.pooling = dec::Harmony::Pooling::sum_likelihood;
        else if (harmony_pooling == "vote")
            harmony_config.pooling = dec::Harmony::Pooling::vote;
        else
            throw std::invalid_argument("Harmony pooling must be sum_likelihood or vote");
    }
    if (decoder_name == "libra" || decoder_name == "seeded" ||
        decoder_name == "harmony" || correlated_pymatching)
        include_opposite_basis_detectors = true;

    // Contributor: OpenAI Codex. Preserve colorless flags in both bases while
    // allowing opposite-basis check detectors to follow the surface-code option.
    // Contributor: OpenAI Codex. Select operation/noise behavior once; geometry
    // and detector generation depend only on the requested code.
    const SI1000NoisePolicy circuit_noise(p);
    const CodeCapacityNoisePolicy capacity_noise(p);
    const PhenomenologicalNoisePolicy pheno_noise(p,measurement_error_rate);
    const CircuitNoisePolicy& operation_policy = code_capacity
        ? static_cast<const CircuitNoisePolicy&>(capacity_noise)
        : phenomenological ? static_cast<const CircuitNoisePolicy&>(pheno_noise)
                           : static_cast<const CircuitNoisePolicy&>(circuit_noise);
    stim::Circuit circuit;
    if (code_name == "cc666")
        circuit = cc666_circuit(d,r,operation_policy,false,include_opposite_basis_detectors,noise_distribution);
    else if (code_name == "cc488")
        circuit = cc488_circuit(d,r,operation_policy,false,include_opposite_basis_detectors,noise_distribution);
    else if (external_code)
        circuit = hyperbolic_color_code_circuit(
            (std::filesystem::path(QUDEC_SOURCE_DIR) / "hyperbolic_color_codes_L2" /
             external_code->directory).string(), static_cast<uint32_t>(r), operation_policy,
            false, include_opposite_basis_detectors, noise_distribution);
    else
        circuit = sc_circuit(d,r,operation_policy,false,include_opposite_basis_detectors,noise_distribution);
    if (world_rank == 0 && noise_distribution.log_stddev > 0)
        std::cout << "Component noise: log_stddev=" << noise_distribution.log_stddev
                  << " model_seed=" << noise_distribution.seed
                  << " nominal_p=" << p << '\n';

    if (world_rank == 0 && (code_capacity || phenomenological))
        std::cout << "Noise model: " << noise_model << " rounds=" << r
                  << " data_p=" << p << " measurement_p=" << (code_capacity ? 0 : measurement_error_rate) << '\n';

    // Color-code decoders need the original correlated DEM events.
    // Graphlike decoders receive their normal decomposed decoding model separately.
    auto dem = stim::circuit_to_dem(circuit, {.decompose_errors = !color_decoder && decoder_name != "tesseract"});

    // Build decoder, run estimation, and report results.
    auto run = [&] (auto&& dec, const auto& error_callback)
    {
        double ler = estimate_logical_error_rate(dem, dec, conf, error_callback);
        dec.mpi_accumulate();
        if (world_rank == 0)
        {
            std::cout << "Logical error rate: " << ler << "\n";
            dec.print_stats(std::cout);
        }
    };

    if (decoder_name == "concat_mwpm")
    {
        if (world_rank == 0)
            std::cout << "ConcatMWPM " << code_name << ' ' << noise_model << ": distance=" << d << " rounds=" << r
                      << " p=" << p << " sampling_seed=" << conf.seed
                      << " boundary_gap=" << concat_boundary_gap
                      << " ensemble_size=" << concat_ensemble_size << " ensemble_seed=" << concat_ensemble_seed
                      << " belief_propagation=" << concat_bp
                      << " flag_renormalization=" << concat_flag_renormalization << '\n';
        run(dec::ConcatMWPM(dem,{
            .boundary_gap=concat_boundary_gap,
            .ensemble_size=static_cast<size_t>(concat_ensemble_size),
            .ensemble_seed=static_cast<uint64_t>(concat_ensemble_seed),.debug=decoder_debug,
            .flag_renormalization=concat_flag_renormalization,.physical_error_rate=p,
            .belief_propagation=concat_bp}), [] (auto, auto, auto) {});
    }
    else if (decoder_name == "pymatching")
    {
        run(dec::PyMatching(dem, {.enable_gap_estimation=enable_gap, .correlated=correlated_pymatching,
                                      .enable_cluster_gap=enable_cluster_gap,
                                      .print_cluster_gap_histogram=print_cluster_gap_histogram}),
            [] (auto, auto, auto) {});
    }
    else if (decoder_name == "harmony")
    {
        if (world_rank == 0)
            std::cout << "Harmony " << noise_model << ": distance=" << d << " rounds=" << r << " p=" << p
                      << " opposite_basis_detectors=true pooling=" << harmony_pooling
                      << " ensemble_size=" << harmony_config.ensemble_size
                      << " sentinel_size=" << harmony_config.sentinel_size
                      << " layered=" << (harmony_config.layered ? "true" : "false")
                      << " sampling_seed=" << conf.seed << " ensemble_seed=" << harmony_config.seed << '\n';
        dec::Harmony harmony(dem, harmony_config);
        harmony.prepare_ensemble();
        run(harmony, [] (auto, auto, auto) {});
    }
    else if (decoder_name == "uf")
    {
        if (world_rank == 0)
            std::cout << "UnionFind " << noise_model << ": distance=" << d << " rounds=" << r << " p=" << p
                      << " opposite_basis_detectors=" << (include_opposite_basis_detectors ? "true" : "false")
                      << " weight_scale=" << uf_weight_scale << " sampling_seed=" << conf.seed << '\n';
        run(dec::UnionFind(dem, {.weight_scale=static_cast<uint64_t>(uf_weight_scale),
                                .enable_cluster_gap=enable_cluster_gap,
                                .print_cluster_gap_histogram=print_cluster_gap_histogram}),
            [] (auto, auto, auto) {});
    }
    else if (decoder_name == "blossom5")
    {
        run(dec::BlossomV(dem), [] (auto, auto, auto) {});
    }
    else if (decoder_name == "tesseract")
    {
        if (world_rank==0)
        {
            std::cout<<"Tesseract "<<noise_model<<": code="<<code_name<<" distance="<<d<<" rounds="<<r<<" p="<<p;
            tesseract_options.print(std::cout);
            std::cout<<'\n';
        }
        run(dec::Tesseract(tesseract_options.make_config(dem)), [] (auto, auto, auto) {});
    }
    else if (decoder_name == "libra")
    {
        if (world_rank == 0)
            std::cout << "Libra " << noise_model << ": distance=" << d << " rounds=" << r << " p=" << p
                      << " opposite_basis_detectors=true ensemble_size=" << libra_config.ensemble_size
                      << " gap_threshold_db=" << libra_config.gap_threshold_db
                      << " sampling_seed=" << conf.seed << " ensemble_seed=" << libra_config.seed << '\n';
        dec::Libra libra(dem, libra_config);
        libra.prepare_ensemble();
        run(libra, [] (auto, auto, auto) {});
    }
    else if (decoder_name == "seeded")
    {
        if (world_rank == 0)
            std::cout << "SeededMatching " << noise_model << ": distance=" << d << " rounds=" << r << " p=" << p
                      << " opposite_basis_detectors=true seed=" << seed_decoder
                      << " second=" << second_decoder << " postprocess=" << seeded_config.postprocess
                      << " seed_gap=" << seed_gap << " seed_gap_threshold_db=" << seeded_config.libra_gap_threshold_db
                      << " sampling_seed=" << conf.seed << '\n';
        auto run_with_seed = [&](auto& seed)
        {
            auto run_pipeline = [&](auto& second)
            {
                dec::SeededMatching pipeline(dem, seed, second, seeded_config);
                run(pipeline, [] (auto, auto, auto) {});
            };
            if (second_decoder == "correlated_pymatching")
            {
                dec::CorrelatedPyMatching second(dem);
                run_pipeline(second);
            }
            else
            {
                dec::Libra second(dem, libra_config);
                second.prepare_ensemble();
                run_pipeline(second);
            }
        };
        const bool cluster_gate = second_decoder == "libra" && seed_gap == "cluster";
        if (seed_decoder == "pymatching")
        {
            dec::PyMatching seed(dem, {.report_matching_data=true,
                                       .enable_cluster_gap=cluster_gate});
            run_with_seed(seed);
        }
        else
        {
            dec::UnionFind seed(dem, {.weight_scale=static_cast<uint64_t>(uf_weight_scale),
                                      .report_matching_data=true,
                                      .enable_cluster_gap=cluster_gate});
            run_with_seed(seed);
        }
    }
    return 0;
}

int main(int argc, char* argv[])
{
    int world_rank = 0;
#if defined(ENABLE_MPI)
    MPI_Init(&argc, &argv);
    MPI_Comm_rank(MPI_COMM_WORLD, &world_rank);
#endif
    int status = 0;
    try {
        status = run_cli(argc, argv, world_rank);
    } catch (const std::exception& error) {
        if (world_rank == 0) std::cerr << argv[0] << ": " << error.what() << '\n';
        status = 1;
#if defined(ENABLE_MPI)
        MPI_Abort(MPI_COMM_WORLD, status);
#endif
    }
#if defined(ENABLE_MPI)
    MPI_Finalize();
#endif
    return status;
}
